        net_name: &str,
        layer_str: &str,
        width_nm: i64,
        segments_flat: &[i64],
    ) -> u32 {
        use cypcb_world::components::trace::{Trace as TraceComp, TraceSegment, TraceSource};

        // Parse layer
        let layer = match parse_layer(layer_str) {
            Ok(l) => l,
            Err(_) => return u32::MAX,
